import csv, json
from collections import defaultdict
d=defaultdict(list)
for r in csv.DictReader(open('thermocouples.csv')):
    d[(r['run_id'],r['tc_id'])].append((int(r['t_s']),float(r['temp'])))
chosen={'R100':'TC3','R101':'TC1','R102':'TC1'}
limit=2.0
maxramp={}
viol=[]
for run,tc in chosen.items():
    v=sorted(d[(run,tc)])
    idx=next(i for i,(t,tp) in enumerate(v) if tp>140)
    seg=v[:idx+1]
    best=0
    for i in range(1,len(seg)):
        t0,tp0=seg[i-1]; t1,tp1=seg[i]
        if tp0>=40 and tp1>=40:
            dt=t1-t0
            ramp=(tp1-tp0)/dt
            best=max(best,ramp)
    maxramp[run]=round(best,2)
    if round(best,2)>limit: viol.append(run)
res={'ramp_limit_c_per_s':limit,'max_preheat_ramp':maxramp,'violating_runs':sorted(viol)}
print(json.dumps(res,indent=2))
import os
os.makedirs('/app/output',exist_ok=True)
open('/app/output/reflow_report.json','w').write(json.dumps(res))
