import csv, json
from datetime import datetime
from collections import defaultdict

limit = 40
micro_min = 3

start = datetime(2026,9,9,22,0)
end = datetime(2026,9,10,6,0)

def in_shift(ts):
    t = datetime.strptime(ts, "%Y-%m-%d %H:%M")
    return start <= t < end

by_machine = defaultdict(list)
machines = set()
with open('/app/data/sensor_log.csv') as f:
    r = csv.DictReader(f)
    for row in r:
        if not in_shift(row['timestamp']):
            continue
        machines.add(row['machine_id'])
        by_machine[row['machine_id']].append(row)

downtime = defaultdict(int)
for m, rws in by_machine.items():
    rws.sort(key=lambda x: x['timestamp'])
    i = 0; n = len(rws)
    while i < n:
        if rws[i]['state'] == 'DOWN':
            j = i
            while j < n and rws[j]['state'] == 'DOWN':
                j += 1
            if (j - i) >= micro_min:
                downtime[m] += (j - i)
            i = j
        else:
            i += 1

result = {
    "limit_min": limit,
    "downtime_by_machine": {m: downtime.get(m,0) for m in sorted(machines)},
    "over_limit": sorted([m for m in machines if downtime.get(m,0) > limit])
}
with open('/app/output/downtime.json','w') as f:
    json.dump(result, f, indent=2)
print(json.dumps(result, indent=2))
for m in sorted(by_machine):
    print(m, "minutes in shift:", len(by_machine[m]))
EOF"}

