import json, math, csv

def hav(lat1,lon1,lat2,lon2):
    R=6371.0
    p1=math.radians(lat1); p2=math.radians(lat2)
    dp=math.radians(lat2-lat1); dl=math.radians(lon2-lon1)
    a=math.sin(dp/2)**2+math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2
    return 2*R*math.asin(math.sqrt(a))

depot=(52.3659,4.80337); speed=40.0
orders={}
with open('data/orders.csv') as f:
    for row in csv.DictReader(f):
        orders[row['order_id']]=(float(row['lat']),float(row['lon']))
def phm(s):
    h,m=s.split(':'); return int(h)*60+int(m)
def rseq(seq):
    d=0.0; t=480; pos=depot
    for o in seq:
        lat,lon=orders[o]
        nd=hav(pos[0],pos[1],lat,lon); d+=nd; t+=nd/speed*60
        if t<phm('09:00') and False: pass
        d+=0
        pos=(lat,lon)
    d+=hav(pos[0],pos[1],*depot)
    return d
v1=['C07','C02','C05','C08','C01']; v2=['C06','C03']
tot=rseq(v1)+rseq(v2)
plan={'routes':{'V1':v1,'V2':v2},'total_km':round(tot,2)}
import os; os.makedirs('output',exist_ok=True)
json.dump(plan,open('output/plan.json','w'),indent=2)
print(json.dumps(plan,indent=2))
""}

